using UnityEngine;using UnityEditor;using System;using System.IO;
namespace Xinghai.MapEditor.Editor {public static class GuiProof {
 static BakeWindow window;static double start;static bool clicked,released;static double downAt;
 public static void Run(){try{EditorApplication.ExecuteMenuItem("星骸地图/烘焙地图");window=EditorWindow.GetWindow<BakeWindow>();window.position=new Rect(100,100,560,480);window.ChooseSource(Path.GetFullPath("../workflow/地图 样本.json"));window.ShowUtility();window.Focus();window.Repaint();start=EditorApplication.timeSinceStartup;EditorApplication.update+=Tick;}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 static void Tick(){try{if(EditorApplication.timeSinceStartup-start>25)throw new Exception("GUI bake timeout: clicked="+clicked+" rect="+window.bakeButtonRect+" status="+MapBaker.LastStatus+"");if(!clicked&&window.bakeButtonRect.width>100){clicked=true;var p=window.bakeButtonRect.center;window.SendEvent(new Event{type=EventType.MouseMove,mousePosition=p});Debug.Log("[DEBUG-GUI] down="+window.SendEvent(new Event{type=EventType.MouseDown,button=0,mousePosition=p}));downAt=EditorApplication.timeSinceStartup;}if(clicked&&!released&&EditorApplication.timeSinceStartup-downAt>.2){released=true;Debug.Log("[DEBUG-GUI] up="+window.SendEvent(new Event{type=EventType.MouseUp,button=0,mousePosition=window.bakeButtonRect.center}));}if(clicked&&(MapBaker.LastStatus=="updated"||MapBaker.LastStatus=="unchanged")){if(Selection.activeObject==null||!AssetDatabase.GetAssetPath(Selection.activeObject).EndsWith("Module.prefab"))throw new Exception("GUI did not select baked module");File.WriteAllText("../logs/gui-bake.json","{\"passed\":true,\"method\":\"real EditorWindow IMGUI mouse events; only source-file selection supplied programmatically\",\"humanOperated\":false}");Debug.Log("XH_GUI_BAKE_PASS");EditorApplication.update-=Tick;window.Close();EditorApplication.Exit(0);}}catch(Exception e){EditorApplication.update-=Tick;Debug.LogException(e);EditorApplication.Exit(1);}}
}}
